#!/usr/bin/env python3
"""Render v0.2 findings from completed experiments and capture source provenance."""
import json,hashlib,tarfile
from catalog import ROOT,CARDS
OUT=ROOT/'results'
def load(n):return json.loads((OUT/n).read_text())
def pct(x):return f'{100*x:.1f}%'
def num(x):return '—' if x is None else f'{x:.2f}'
def table(h,rows):return '\n'.join(['| '+' | '.join(h)+' |','|'+'|'.join(['---']*len(h))+'|']+['| '+' | '.join(map(str,r))+' |' for r in rows])+'\n'
def main():
 names=['combat.json','refinement.json','advanced.json','healing-timing.json','revision.json']
 by={n:load(n) for n in names};rows=sum(by.values(),[]);rev=by['revision.json'];campaign=load('campaigns.json');wc=load('wound-campaigns.json')
 with tarfile.open(ROOT/'history/v0.1.tar.gz') as tar:old=json.load(tar.extractfile('playtest/results/refinement.json'))
 def anchor(rs):return [r for r in rs if r['group']=='refinement' and r['ehp']==14 and r['damage']==[5,6,8] and r['target']=='spread' and r.get('threshold')==.5]
 total=sum(r['trials'] for r in rows)+sum(r['reached'] for r in campaign+wc)
 text=['# Revised working playtest findings — v0.2','', 'October 12, 2026. Test catalog refresh for issues #1127 and #1128. Results are measured under the [model contract](../tests/README.md), not a declaration that HOL is balanced.','',f'**{total:,} encounter trials:** {len(rows)} isolated configurations ({sum(r["trials"] for r in rows):,} encounters), plus {sum(r["reached"] for r in campaign+wc):,} encounters in 7,000 sequences. Separately: 240,000 local grapple trials. 38 saved character snapshots; {len(CARDS)} purchased/signature prototypes; 11 universal references.','', '## Same anchor, revised rules','','Four level-1 PCs versus four HP-14 enemies, Physical resistance 1, damage 5/6/8, spread targeting. Owned armor/shields and spare-Maneuver Defend; no potions or active wound overlay. This is the original anchor, not a newly tuned encounter.', '',table(['Version','Healing','Rounds','Any party wound','Healing actions','Caster HP spent','Timeout'],[(v,r['policy'],num(r['rounds']),pct(r['any_wound']),num(r['heals']),num(r.get('healing_cost',0)),pct(r['timeout'])) for v,rs in [('v0.1',old),('v0.2',by['refinement.json'])] for r in anchor(rs)]),'The comparison changes the approved rules together, including Protector HP. It does not isolate healing alone. Soft targets remain about four rounds and 20–30% party wound chance without a healer, 5–15% with one. At 3,000 trials, the worst-case 95% sampling margin is ±1.8 percentage points; model omissions matter more.','']
 current=anchor(by['refinement.json']);nh=next(r for r in current if r['policy']=='none');h=next(r for r in current if r['policy']=='one')
 text+=['## Takeaways for the next discussion','',f'- The original anchor now gives **{num(nh["rounds"])} rounds / {pct(nh["any_wound"])} wound chance without healing**, and **{num(h["rounds"])} rounds / {pct(h["any_wound"])} with one healer**. The healer result is close to the lower edge of the soft target; this does not require immediate retuning.','- Fixed healing removes the old unlimited full-HP restoration loop in the tested solo-healer fixtures. This is evidence for the new model, not proof that no future card can create a loop.','- Even Lesser potions strongly reduce wounds because their Maneuver cost preserves offense. Supply, access and price deserve attention before increasing healing numbers.','- Forcing higher-tier healing at the same half-HP trigger can increase wounds: extra caster cost and over-healing can outweigh restoration. Prefer testing additional benefits or smarter tier choice over assuming bigger raw numbers are sufficient.','- Higher basic damage helps basic-only stress fights, but has little effect when purchased attacks dominate. Test its opportunity/free-attack role before adopting a universal increase.','']
 text+=['## Basic attacks: do higher values matter?','','“Basic only” voluntarily suppresses purchased attacks; it is a stress test, not an optimal build. “Full catalog” chooses the best ordinary learned damage card. Free attacks and opportunity damage are not multiplied in this comparison.', '',table(['Profile','Resistance','Basic only','Healing','Rounds','Any wound'],[(r['basic_profile'],r['eres'],r['basic_only'],r['policy'],num(r['rounds']),pct(r['any_wound'])) for r in rev if r['case']=='basic_damage']), 'Against resistance 3, 2/3/5 becomes 1/1/2 and 3/4/6 becomes 1/1/3. If the full-catalog result barely changes, that means characters chose purchased attacks; it does not prove basic damage is irrelevant to opportunity/free-attack abilities.','']
 text+=['## Life resistance and potions','','Life resistance protects against damage but also reduces restoration, minimum 1. Caster cost is never reduced. All-healer means every PC who actually learned Mend may choose it; it does not grant free cards.', '',table(['Life resistance','Healing policy','Rounds','Any wound','Heals','Caster HP cost'],[(r['pc_life_res'],r['policy'],num(r['rounds']),pct(r['any_wound']),num(r['heals']),num(r['healing_cost'])) for r in rev if r['case']=='life_resistance']), '',table(['Potion HP','Healing policy','Rounds','Any wound','Potion uses'],[(r['potion_healing'],r['policy'],num(r['rounds']),pct(r['any_wound']),num(r['potions_used'])) for r in rev if r['case']=='potions']), 'Each potion scenario supplies one d4 bottle per PC. Strength and supply are separate. These are explicitly supplied consumables, not starting grants or an economic recommendation.','']
 text+=['## Healing tiers and enemy healing','','Greater Mend and Deep Restoration are actual purchasable prototypes. The Shepherd progression buys the discipline ranks and cards. Requested higher-tier healing falls back to Mend if not learned. The enemy tier tests explicitly supply the indicated healing ability; NPC support roll Reason +1 remains a test convention.', '',table(['Party level','Requested tier','Rounds','Any wound','Heals','HP cost'],[(r['level'],r['healing_tier'],num(r['rounds']),pct(r['any_wound']),num(r['heals']),num(r['healing_cost'])) for r in rev if r['case']=='learned_healing_tier']), '',table(['Enemy healing tier','Rounds','Timeout','Enemy heals','Enemy HP cost'],[(r['enemy_healing_tier'],num(r['rounds']),pct(r['timeout']),num(r['enemy_heals']),num(r['enemy_healing_cost'])) for r in rev if r['case']=='enemy_tier']), 'A higher casting cost is not assumed to make a card better. Actual net healing, over-healing and opportunity costs must justify purchase. Higher signatures remain disabled in these encounters.','']
 text+=['## Original one-feature layers, rerun','','Same HP-12 focus-fire fixture as the first pass, not the spread-targeting anchor. Opportunity attacks assume contact; no map movement or Disengage policy is modeled. Strong-interrupt is still an experimental alternative, not adopted canon.', '',table(['Layer','Healing','Rounds','Any wound','Timeout'],[(r['layer'],r['policy'],num(r['rounds']),pct(r['any_wound']),pct(r['timeout'])) for r in by['combat.json'] if r['group']=='layer']), 'Burning now ticks then decays. The ordinary pressure layer does not choose to extinguish during combat. End-of-fight assistance remains explicit.','']
 text+=['## Wound effects: bounded overlay, not a board simulation','','These runs select real wound entries and apply temporary disabling conditions, ongoing damage, persistent sensory conditions and broad activity Banes. Immediate forced movement, Prone movement cost, and lasting Speed penalties are recorded/described but cannot affect positioning in this no-map engine. Consequently these are partial wound tests. Different damage types bypass different armor; compare overlay off/on within a type, not types as if armor were equal.', '',table(['Damage type','Overlay','Healing','Rounds','Any wound','Any terminal PC','Disabled turns'],[(r['enemy_type'],r['active_wounds'],r['policy'],num(r['rounds']),pct(r['any_wound']),pct(r['any_terminal']),num(r['disabled_turns'])) for r in rev if r['case']=='wound_overlay']), 'Duration-only blindness prevents direct attack targeting in the overlay. Defense while blind uses three Banes as a declared stress convention; DA visibility rulings are not a completed perception system. Frightened assumes the source stays perceptible while combat lasts.','']
 text+=['## Ten-encounter sequences','','Full-HP breaths, no Grit refill, permanent scars, stop at first terminal PC or failed encounter. First table leaves active wound penalties off for historical comparison.', '',table(['Healing','Potions','Resupply','Encounter','Full-party completion','Grit remaining','Scars'],[(r['policy'],r['potions'],r['resupply'],r['encounter'],pct(r['full_party_completion']),num(r['mean_grit_remaining']),num(r['mean_scars'])) for r in campaign if r['encounter'] in (5,10)]),'', 'The second table includes the bounded wound overlay. Treatment means a safe day after each encounter, only with capabilities the party actually purchased. The field is permission to attempt treatment, not a guarantee that the party knows the needed card.', '',table(['Damage type','Treatment allowed','Encounter','Completion','Scars','Untreated lasting wounds','Treatment attempts'],[(r['source'],r['treatment'],r['encounter'],pct(r['full_party_completion']),num(r['mean_scars']),num(r['mean_untreated']),r['treatment_attempts']) for r in wc if r['encounter'] in (5,10)]),'Treatment rolls currently omit injury penalties on the healer: these are optimistic downtime results. They are not full campaign survival forecasts, particularly because mobility and collision effects remain unmodeled.','']
 text+=['## Catalog and rule cleanup','','- Protector HP is +5; all class HP contributions are approved fixtures. Creation, acquisition deduplication, stage expiry and rank gates were rerun. See [creation](creation.md) and [variants](variants.md).','- Six treatment capabilities now have prototype cards. Their Life 1 requirement, attributes, one-hour interval and shared Novice price are explicit assumptions, not approved final card balance.','- Ordinary Recipes is repeatable at 2 DP for two new compatible recipes. The small four-recipe kit allows only one extra purchase after Field Craft until more recipes are added; the rule itself has no purchase-count limit.','- Field Dressing no longer provides an uncosted percentage heal. It is a provisional nonmagical Bleeding-removal ability, excluded from baseline encounters.','- Resistance caps at 3. Wall of Iron and Last Bastion were capped accordingly; this makes their resistance benefit redundant for some heavy-armor users. They need redesign before higher-tier signature certification. No substitute power was silently invented.','- Summon tether and grapple attack Boons are in card text and local checks. Unlimited nearby bodies, actual forced movement and rescue tactics still need mapped play.','- No separate observation roll was introduced. Careful Observer is a Reason-based card; perception/detection remains an open core discussion.','', '## What follows from this pass','','Use the anchor and sensitivity tables to choose the next numerical adjustment; do not infer difficulty from round count alone. Next test level-1 signature choices on declared boards, then grapple/tether/forced movement interactions. Extend treatment access and higher-tier cards after seeing those results. Encounter CV remains provisional; the old CV fit has not been relabeled as current. Layout is still deferred.','']
 (OUT/'findings.md').write_text('\n'.join(text))
 manifest=dict(revision='v0.2',result_files=names,isolated_configurations=len(rows),isolated_encounters=sum(r['trials'] for r in rows),campaign_sequences=7000,campaign_encounters=sum(r['reached'] for r in campaign+wc),total_encounters=total,build_snapshots=38,local_grappling_trials=240000,catalog_cards=len(CARDS),combat_checks=load('combat-validation.json')['checks'],input_sha256={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(list(ROOT.glob('*.md'))+[ROOT/'catalog.json']+list((ROOT/'tests').glob('*.py')))},output_sha256={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(OUT.glob('*.json')) if p.name not in ['manifest.json','verification.json']},historical_archive_sha256=hashlib.sha256((ROOT/'history/v0.1.tar.gz').read_bytes()).hexdigest())
 (OUT/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
 print(f'Report generated: {total:,} encounter trials')
if __name__=='__main__':main()
